    "summaryZh": "2026-08-16 百度热搜第 9 名，热度 713.7万。8月14日晚，苏州吴中区太湖旁一小区因暴雨湖水倒灌致车库被淹。该小区一业主称，当晚自己发现车库进水情况，第一时间就在业主群进行通知，但还是有部分业主没来得及下去移车。15日，小区物业管家表示，现在小区车库正在进行抽水，水位已经下降，但不清楚什么时候能够清理完成。",
